 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)
    template_comp = max(comps, key=len)
    template_set = set(template_comp)
    min_r = min(r for r, c in template_comp)
    max_r = max(r for r, c in template_comp)
    min_c = min(c for r, c in template_comp)
    max_c = max(c for r, c in template_comp)
    template = [[grid[r][c] if (r, c) in template_set else bg
                 for c in range(min_c, max_c + 1)]
                for r in range(min_r, max_r + 1)]
    anchor_r, anchor_c = (len(template) - 1) // 2, (len(template[0]) - 1) // 2

    other = [grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != bg and (r, c) not in template_set]
    marker = Counter(other).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r, c) not in template_set:
                for tr, row in enumerate(template):
                    for tc, value in enumerate(row):
                        y, x = r + tr - anchor_r, c + tc - anchor_c
                        if 0 <= y < h and 0 <= x < w:
                            out[y][x] = value
    return out
